def hex_key(num):
    """Counts the number of hexadecimal digits in the input string that are prime numbers.
    Prime hexadecimal digits are 2, 3, 5, 7, B (11), D (13).
    """
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in prime_hex_digits)
